<script setup lang="ts">
import MarkLegend from './MarkLegend.vue'
import {computed,onMounted,ref,watch} from 'vue'
import {scheduleApi} from '../schedules'
const props=defineProps<{homeworkId:number}>()
const emit=defineEmits<{busy:[value:boolean];dirty:[value:boolean]}>()
const students=ref<any[]>([]),loading=ref(false),saving=ref(false),error=ref(''),message=ref(''),search=ref(''),filter=ref('')
const statuses=[['pending','Pending'],['submitted','O · Done'],['missing','X · Not done'],['late','– · Late submission'],['reviewed','Reviewed']]
const visible=computed(()=>students.value.filter(s=>(!filter.value||s.saved===filter.value)&&(s.full_name+' '+s.login_id).toLowerCase().includes(search.value.toLowerCase().trim())))
const changed=computed(()=>students.value.filter(s=>s.status!==s.saved))
watch(changed,()=>emit('dirty',changed.value.length>0),{deep:true})
async function refresh(){if(students.value.some(s=>s.status!==s.saved)&&!window.confirm('Discard unsaved statuses and refresh?'))return;await load()}
async function load(){loading.value=true;error.value='';try{const r=await scheduleApi(`teacher/homework/${props.homeworkId}/progress`);students.value=r.students.map((s:any)=>({...s,saved:s.status}))}catch(e){error.value=e instanceof Error?e.message:'Unable to load progress.'}finally{loading.value=false}}
async function saveAll(){if(!changed.value.length||saving.value)return;const records=changed.value.map(s=>({student_user_id:s.id,status:s.status,version:s.version}));saving.value=true;emit('busy',true);error.value='';message.value='';try{const r=await scheduleApi(`teacher/homework/${props.homeworkId}/progress`,'PUT',{records});for(const mark of r.records){const s=students.value.find(s=>s.id===mark.student_user_id);if(s){s.saved=mark.status;s.status=mark.status;s.version=mark.version}}message.value=r.message}catch(e){error.value=e instanceof Error?e.message:'Unable to save updates.'}finally{saving.value=false;emit('busy',false)}}
onMounted(load)
</script>
<template><section class="homework-tracking"><MarkLegend kind="homework" /><p class="muted">Record work received in class. Students and linked parents can see saved statuses.</p><p v-if="loading" role="status">Loading students…</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p><div class="tracking-summary"><span v-for="[value,label] in statuses" :key="value">{{label}} <strong>{{students.filter(s=>s.saved===value).length}}</strong></span></div><div class="tracking-filters"><label>Find a student<input v-model="search" type="search" placeholder="Name or student ID"></label><label>Status<select v-model="filter"><option value="">All statuses</option><option v-for="[value,label] in statuses" :key="value" :value="value">{{label}}</option></select></label><button type="button" class="secondary" :disabled="loading||!!saving" @click="refresh">Refresh</button></div><p v-if="!loading&&!error&&!visible.length">No students match.</p><div v-for="s in visible" :key="s.id" class="tracking-student"><div><strong>{{s.full_name}}</strong><small>{{s.login_id}}</small></div><label><span class="tracking-sr">Status for {{s.full_name}}</span><select v-model="s.status" :disabled="!!saving"><option v-for="[value,label] in statuses" :key="value" :value="value">{{label}}</option></select></label></div><div class="tracking-savebar"><span role="status">{{changed.length?changed.length+' unsaved update(s), including hidden rows':students.length?'All changes saved':'No changes to save'}}</span><button type="button" :disabled="loading||saving||!changed.length" @click="saveAll">{{saving?'Saving…':'Save all changes'}}</button></div></section></template>
<style scoped>
.tracking-summary{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}.tracking-summary span{background:#eef4f0;padding:8px 10px;border-radius:8px;font-size:13px}.tracking-filters{display:flex;align-items:end;flex-wrap:wrap;gap:12px}.tracking-filters label{flex:1;min-width:140px}.homework-tracking input,.homework-tracking select{width:100%;font:inherit;font-size:16px;padding:10px;border:1px solid #bccfc5;border-radius:8px;background:white;color:#243e33}.homework-tracking label{margin:0}.homework-tracking button{width:auto;margin:0;min-height:44px;padding:10px 14px;font-size:14px}.tracking-student{display:grid;grid-template-columns:minmax(0,1fr) 160px;align-items:center;gap:12px;padding:14px 0;border-bottom:1px solid #dce5df;font-size:15px}.tracking-student small{display:block;color:#60736e;font-size:12px;margin-top:4px}.tracking-savebar{position:sticky;bottom:0;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;padding:14px 0 4px;margin-top:12px;background:#fff;border-top:1px solid #dce5df}.tracking-savebar span{font-size:12px;color:#60736e}.tracking-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}@media(max-width:480px){.tracking-student{grid-template-columns:minmax(0,1fr) auto;gap:8px}.tracking-student>div{grid-column:1/-1}.tracking-student label{width:100%}}
</style>
